function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

function wrap(fn) {
  return function (...args) {          // regular function: receives the caller's this
    // ...extra behaviour before/after...
    return fn.apply(this, args);       // forward both this and the arguments
  };
}

