const wait = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms));
const getUser = () => wait(300, { id: 7, name: 'Nadia' });
const getOrders = () => wait(200, ['#101', '#102']);
const getCart = () => wait(100, { items: 3 });

// Sequential: each await waits for the previous request (~600 ms)
async function loadSequential() {
  const user = await getUser();
  const orders = await getOrders();
  const cart = await getCart();
  return { user, orders, cart };
}

// Parallel: start all three first, then wait for all (~300 ms = the slowest)
async function loadParallel() {
  const [user, orders, cart] = await Promise.all([getUser(), getOrders(), getCart()]);
  return { user, orders, cart };
}

// A rejected promise becomes a thrown error inside async functions
async function safeLoad() {
  try {
    return await loadParallel();
  } catch (err) {
    console.error('Load failed:', err.message);
    return null;
  } finally {
    console.log('hide spinner');
  }
}

