function debounce(fn, wait) {
  let timerId = null;
  return function (...args) {
    clearTimeout(timerId);          // every new call cancels the pending one
    timerId = setTimeout(() => {
      timerId = null;
      fn.apply(this, args);         // runs once calls stop for `wait` ms
    }, wait);
  };
}

function throttle(fn, wait) {
  let last = -Infinity;             // time of the last real call
  return function (...args) {
    const now = Date.now();
    if (now - last >= wait) {       // at most one call per `wait` ms
      last = now;
      fn.apply(this, args);
    }
  };
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Consumer;

public class RateLimit {
    private static final ScheduledExecutorService TIMER = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread t = new Thread(r, "debounce-timer");
        t.setDaemon(true);
        return t;
    });

    /** Runs fn only after waitMs pass with no new calls. */
    public static <T> Consumer<T> debounce(Consumer<T> fn, long waitMs) {
        AtomicReference<ScheduledFuture<?>> pending = new AtomicReference<>();
        return arg -> {
            ScheduledFuture<?> next = TIMER.schedule(() -> fn.accept(arg), waitMs, TimeUnit.MILLISECONDS);
            ScheduledFuture<?> prev = pending.getAndSet(next);
            if (prev != null) prev.cancel(false);   // a new call cancels the pending one
        };
    }

    /** Runs fn at most once every waitMs (leading edge). */
    public static <T> Consumer<T> throttle(Consumer<T> fn, long waitMs) {
        long waitNanos = TimeUnit.MILLISECONDS.toNanos(waitMs);
        AtomicLong last = new AtomicLong(System.nanoTime() - waitNanos); // first call passes
        return arg -> {
            long now = System.nanoTime();
            long prev = last.get();
            if (now - prev >= waitNanos && last.compareAndSet(prev, now)) {
                fn.accept(arg);
            }
        };
    }
}

