// Polyfill: call = "temporarily make fn a method of ctx, then call it"
Function.prototype.myCall = function (ctx, ...args) {
  ctx = ctx == null ? globalThis : Object(ctx);   // box primitives like call does
  const key = Symbol('fn');                       // unique: cannot clash with ctx's keys
  ctx[key] = this;                                // this = the function being called
  const result = ctx[key](...args);               // implicit binding: this = ctx
  delete ctx[key];
  return result;
};

Function.prototype.myBind = function (ctx, ...preset) {
  const fn = this;
  return function (...later) {
    return fn.apply(ctx, [...preset, ...later]);
  };
};

