Array.prototype.myMap = function (callback, thisArg) {
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const len = this.length;
  const result = new Array(len);
  for (let i = 0; i < len; i++) {
    if (i in this) result[i] = callback.call(thisArg, this[i], i, this); // skip holes
  }
  return result;
};

Array.prototype.myFilter = function (callback, thisArg) {
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const len = this.length;
  const result = [];
  for (let i = 0; i < len; i++) {
    if (i in this && callback.call(thisArg, this[i], i, this)) result.push(this[i]);
  }
  return result;
};

Array.prototype.myReduce = function (callback, ...init) {
  if (typeof callback !== 'function') throw new TypeError(callback + ' is not a function');
  const len = this.length;
  let i = 0;
  let acc;
  if (init.length > 0) {
    acc = init[0];                                  // initial value given
  } else {
    while (i < len && !(i in this)) i++;            // first real element
    if (i >= len) throw new TypeError('Reduce of empty array with no initial value');
    acc = this[i++];
  }
  for (; i < len; i++) {
    if (i in this) acc = callback(acc, this[i], i, this);
  }
  return acc;
};

