import java.util.*;
import java.util.function.*;

public class ArrayFns {
    public static <T, R> List<R> map(List<T> items, Function<T, R> fn) {
        List<R> result = new ArrayList<>(items.size());
        for (T x : items) result.add(fn.apply(x));
        return result;
    }

    public static <T> List<T> filter(List<T> items, Predicate<T> keep) {
        List<T> result = new ArrayList<>();
        for (T x : items) if (keep.test(x)) result.add(x);
        return result;
    }

    public static <T, A> A reduce(List<T> items, BiFunction<A, T, A> fn, A initial) {
        A acc = initial;
        for (T x : items) acc = fn.apply(acc, x);
        return acc;
    }

    public static <T> T reduce(List<T> items, BinaryOperator<T> fn) {
        if (items.isEmpty()) throw new NoSuchElementException("reduce of empty list with no initial value");
        T acc = items.get(0);                       // first element becomes the accumulator
        for (int i = 1; i < items.size(); i++) acc = fn.apply(acc, items.get(i));
        return acc;
    }
}

