function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) {
      return fn.apply(this, args);           // enough arguments: call fn
    }
    return function (...more) {              // not enough: wait for more
      return curried.apply(this, [...args, ...more]);
    };
  };
}

