import inspect


def curry(fn, arity=None):
    if arity is None:
        arity = len(inspect.signature(fn).parameters)

    def curried(*args):
        if len(args) >= arity:
            return fn(*args)                      # enough arguments: call fn
        return lambda *more: curried(*args, *more)  # not enough: wait for more

    return curried


