import java.util.*;
import java.util.function.Function;

public class Currying {
    /** A function that accepts any number of arguments (Java has no variadic generic functions). */
    @FunctionalInterface
    public interface Curried {
        Object call(Object... args);
    }

    /** fn receives all collected arguments as a list once `arity` of them have arrived. */
    public static Curried curry(Function<List<Object>, Object> fn, int arity) {
        return collect(fn, arity, List.of());
    }

    private static Curried collect(Function<List<Object>, Object> fn, int arity, List<Object> soFar) {
        return (Object... args) -> {
            List<Object> all = new ArrayList<>(soFar);
            all.addAll(Arrays.asList(args));
            if (all.size() >= arity) return fn.apply(all);   // enough arguments: call fn
            return collect(fn, arity, all);                   // not enough: wait for more
        };
    }

    // Idiomatic typed alternative for a fixed arity:
    // Function<Integer, Function<Integer, Function<Integer, Integer>>> vol = l -> w -> h -> l * w * h;
}

